import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Casas 2012 - Fig. 4 (reference, 50/50, 15 bar, 25 C)'
sim.info.description = 'Binary CO2/H2 breakthrough on AP3-60 activated carbon, reproducing the reference experiment of Casas et al. (2012), Fig. 4: an equimolar CO2/H2 feed at 15 bar and 25 C. The bed is initially pressurised with inert helium and then fed the CO2/H2 mixture at a constant superficial flow of 10 cm3/s. A competitive Sips isotherm (parameters from the companion equilibrium study, Schell et al. 2012) describes the equilibrium; mass transfer uses lumped LDF coefficients fitted in the paper.'
sim.info.author = 'Sam Affleck'

# ---- fluid --------------------------------------------------------------------
sim.add_component('CarbonDioxide')
sim.add_component('Hydrogen')
sim.add_component('Helium')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['CarbonDioxide'] = 0.0
sim.fluid.adsorbed_heat_capacity['Hydrogen'] = 0.0
sim.fluid.adsorbed_heat_capacity['Helium'] = 0.0

# ---- adsorbents -----------------------------------------------------------------
ads_ap3_60 = sim.add_adsorbent('AP3-60', solid_density=850.0, heat_capacity=1000.0, thermal_conductivity=0.15, particle_void_fraction=0.5685279187817258)
ads_ap3_60.set_isotherm('arrhenius_sips', {
    'CarbonDioxide': {'n_inf_a': 1.38286, 'n_inf_b': 5625.93, 'k_A': 1.6814e-08, 'k_B': 9160.22, 'c_ref': 0.832365, 'c_amp': 0.116571, 'c_beta': 0.0928714, 'c_Tref': 330.129},
    'Hydrogen': {'n_inf_a': 6.66, 'n_inf_b': 0.0, 'k_A': 6.6886e-10, 'k_B': 9954.73, 'c_ref': 0.96, 'c_amp': 0.0, 'c_beta': 0.0, 'c_Tref': 298.15},
}, components=['CarbonDioxide', 'Hydrogen'])
ads_ap3_60.set_isotherm('inert', components=['Helium'])
ads_ap3_60.set_rate_model('CarbonDioxide', 'ldf', 'constant', k=0.15)
ads_ap3_60.set_rate_model('Hydrogen', 'ldf', 'constant', k=1.0)
ads_ap3_60.set_rate_model('Helium', 'ldf', 'constant', k=0.5)
ads_ap3_60.heat_of_adsorption['CarbonDioxide'] = 26000.0
ads_ap3_60.heat_of_adsorption['Hydrogen'] = 9800.0
ads_ap3_60.heat_of_adsorption['Helium'] = 0.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.025)
sim.bed.ambient_temperature = 298.15
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=8000.0, heat_capacity=500.0, thermal_conductivity=0.0)
sim.wall.thickness = 0.0075
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_ap3_60 = sim.add_layer('AP3-60', composition={'AP3-60': 1.0}, momentum='kozeny_carman', length=1.2, cells=60, bed_void_fraction=0.403, particle_diameter=0.003)
layer_ap3_60.set_dispersion('ruthven', molecular_diffusion_coefficient=1.6e-05)
layer_ap3_60.set_heat_dispersion('constant', heat_dispersion_coefficient=0.0)
layer_ap3_60.set_internal_heat_transfer('leva', leva_eta1=41.13, leva_eta2=0.32, leva_exp_coeff=6.0)
layer_ap3_60.set_external_heat_transfer('constant', external_htc=5.0)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 1500000.0
sim.initial_conditions.temperature = 298.15
sim.initial_conditions.wall_temperature = 298.15
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Helium'] = 1.0
sim.initial_conditions.y['Hydrogen'] = 0.0
sim.initial_conditions.y['CarbonDioxide'] = 0.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 1
sim.cycle.step_time_mode = 0
feed = sim.add_step('Feed', time=1800.0)
feed.bottom.set_streams('inlet', [
    sk.Stream('CO2/H2 Feed', flow=sk.volumetric_flow(1e-05), y={'Helium': 0.0, 'Hydrogen': 0.5, 'CarbonDioxide': 0.5}, temperature=298.15),
])
feed.top.set_pressure('outlet', 1500000.0, y={'CarbonDioxide': 0.0, 'Hydrogen': 0.0, 'Helium': 1.0}, temperature=293.0)

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 0.0
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 0
sim.css.min_cycles = 5
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
